def increment_word(counts, word):
    counts[word] = counts.get(word, 0) + 1
    return counts

# Example usage:
counts = {"apple": 2, "banana": 0}
increment_word(counts, "banana")  # returns {"apple": 2, "banana": 1}
increment_word(counts, "cherry")  # returns {"apple": 2, "banana": 1, "cherry": 1}
